144: // =======================================================================================
145: // id(1) handling
146: //
147: // We can't use getpwnam(), etc. in a static binary, so we shell out to id(1) instead.
148: // This is to set credentials to our user account before we start the server.
149: 
150: namespace idParser {
151: // A KJ parser for the output of id(1).
152: 
153: #pragma GCC diagnostic push
154: #pragma GCC diagnostic ignored "-Wglobal-constructors"
155: 
156: namespace p = kj::parse;
157: using Input = p::IteratorInput<char, const char*>;
158: 
159: template <char delimiter, typename SubParser>
160: auto delimited(SubParser& subParser) -> decltype(auto) {
161:   // Create a parser that parses several instances of subParser separated by the given delimiter.
162: 
163:   typedef p::OutputType<SubParser, Input> Element;
164:   return p::transform(p::sequence(subParser,
165:       p::many(p::sequence(p::exactChar<delimiter>(), subParser))),
166:       [](Element&& first, kj::Array<Element>&& rest) {
167:     auto result = kj::heapArrayBuilder<Element>(rest.size() + 1);
168:     result.add(kj::mv(first));
169:     for (auto& e: rest) result.add(kj::mv(e));
170:     return result.finish();
171:   });
172: }
173: 
174: constexpr auto username = p::charsToString(p::oneOrMore(
175:     p::nameChar.orAny("-.$").orRange(0x80, 0xff)));
176: // It's a bit ambiguous what characters are allowed in usernames. Usually usernames must match:
177: //     ^[a-z_][a-z0-9_-]*[$]?$
178: // However, it seems this may be configurable. We'll try to be lenient here by allowing letters,
179: // digits, -, _, ., $, and any non-ASCII character.
180: 
181: constexpr auto nameNum = p::sequence(p::integer, p::discard(p::optional(
182:     p::sequence(p::exactChar<'('>(), username, p::exactChar<')'>()))));
183: 
184: struct Assignment {
185:   kj::String name;
186:   kj::Array<uint64_t> values;
187: };
188: 
189: auto assignment = p::transform(
190:     p::sequence(p::identifier, p::exactChar<'='>(), delimited<','>(nameNum)),
191:     [](kj::String&& name, kj::Array<uint64_t>&& ids) {
192:   return Assignment { kj::mv(name), kj::mv(ids) };
193: });
194: 
195: auto parser = p::sequence(delimited<' '>(assignment), p::discardWhitespace, p::endOfInput);
196: 
197: #pragma GCC diagnostic pop
198: 
199: }  // namespace idParser
